BEGIN TRANSACTION;
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv6r000013nrv1h8nfvr','kyoto-japan','Kyoto','Japan','Kansai',35.0116,135.7681,'Kyoto is Japan''s ancient capital, home to over a thousand temples, traditional tea houses, and bamboo groves. The city holds centuries of imperial history and remains the cultural heart of Japan.','https://images.unsplash.com/photo-1545569341-9eb8b30979d9?w=1600&q=80','https://images.unsplash.com/photo-1545569341-9eb8b30979d9?w=640&q=80','Florian Wehde on Unsplash','Fushimi Inari shrine torii gates in Kyoto at dawn','JPY','Mar–May, Oct–Nov',3,'temperate',5,NULL,NULL,'culture,food,history',1795037525667,1795071822828);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv6w000613nrp2j7y186','bali-indonesia','Bali','Indonesia','Bali Province',-8.3405,115.092,'Bali is an Indonesian island known for its forested volcanic mountains, terraced rice paddies, beaches, and coral reefs. Hindu temples, traditional dance, and elaborate ceremonies define the local culture.','https://images.unsplash.com/photo-1537953773345-d172ccf13cf1?w=1600&q=80','https://images.unsplash.com/photo-1537953773345-d172ccf13cf1?w=640&q=80','Artem Bryzgalov on Unsplash','Terraced rice paddies in Ubud, Bali at sunrise','IDR','Apr–Oct',2,'tropical',4,NULL,NULL,'culture,relaxation,food,adventure',1795037525673,1795071822833);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv6y000913nra08nqns7','paris-france','Paris','France','Ile-de-France',48.8566,2.3522,'Paris is the capital of France and one of the world''s great cultural centres. Its museums, cuisine, architecture, and fashion have influenced global culture for centuries.','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=1600&q=80','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=640&q=80','Chris Karidis on Unsplash','The Eiffel Tower at dusk from across the Seine','EUR','Apr–Jun, Sep–Oct',4,'temperate',5,NULL,NULL,'culture,food,history,relaxation',1795037525674,1795071822835);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv70000c13nrx7jgihzo','istanbul-turkey','Istanbul','Turkey','Marmara',41.0082,28.9784,'Istanbul is a transcontinental city straddling Europe and Asia. It carries layers of Byzantine, Ottoman, and modern Turkish history, expressed through its grand mosques, bazaars, and Bosphorus waterways.','https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?w=1600&q=80','https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?w=640&q=80','Sulthan Auliya on Unsplash','Blue Mosque and Hagia Sophia skyline at sunset in Istanbul','TRY','Apr–May, Sep–Oct',2,'mediterranean',5,NULL,NULL,'culture,food,history',1795037525676,1795071822836);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv71000d13nrm31edsk4','new-york-usa','New York City','United States','New York State',40.7128,-74.006,'New York City is a global metropolis of unmatched cultural density. Its five boroughs hold world-class museums, a diverse culinary scene, iconic skyline, and a pace of life found nowhere else.','https://images.unsplash.com/photo-1534430480872-3498386e7856?w=1600&q=80','https://images.unsplash.com/photo-1534430480872-3498386e7856?w=640&q=80','Luca Bravo on Unsplash','Manhattan skyline seen from the Brooklyn Bridge at night','USD','Apr–Jun, Sep–Nov',5,'temperate',5,NULL,NULL,'culture,food,nightlife,shopping',1795037525678,1795071822838);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv73000e13nrjo9pl75j','cape-town-south-africa','Cape Town','South Africa','Western Cape',-33.9249,18.4241,'Cape Town sits at the meeting point of two oceans, beneath the flat-topped Table Mountain. The city blends natural drama with a vibrant food scene, diverse neighbourhoods, and a complex, layered history.','https://images.unsplash.com/photo-1580060839134-75a5edca2e99?w=1600&q=80','https://images.unsplash.com/photo-1580060839134-75a5edca2e99?w=640&q=80','Tobias Cornille on Unsplash','Table Mountain above Cape Town at dawn','ZAR','Nov–Mar',2,'mediterranean',4,NULL,NULL,'adventure,culture,food,relaxation',1795037525679,1795071822839);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv74000f13nr8mj67azv','reykjavik-iceland','Reykjavik','Iceland','Capital Region',64.1265,-21.8174,'Reykjavik is the world''s northernmost capital, a compact city of colourful houses and geothermal pools. It serves as the base for Iceland''s volcanic landscapes, geysers, waterfalls, and Northern Lights.','https://images.unsplash.com/photo-1476610182048-b716b8518aae?w=1600&q=80','https://images.unsplash.com/photo-1476610182048-b716b8518aae?w=640&q=80','Davide Cantelli on Unsplash','Northern Lights over Reykjavik harbour','ISK','Jun–Aug (summer), Nov–Feb (Northern Lights)',5,'alpine',3,NULL,NULL,'adventure,nature',1795037525680,1795071822840);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv75000g13nrq70vrxhp','marrakech-morocco','Marrakech','Morocco','Marrakech-Safi',31.6295,-7.9811,'Marrakech is a city of contrasts: its ancient medina of souks, mosques, and riads exists alongside contemporary art galleries and restaurants. The Djemaa el-Fna square pulses with storytellers, musicians, and food vendors at dusk.','https://images.unsplash.com/photo-1539650116574-75c0c6d73f3e?w=1600&q=80','https://images.unsplash.com/photo-1539650116574-75c0c6d73f3e?w=640&q=80','Arthur Yeti on Unsplash','Colourful tagines and spices in a Marrakech souk','MAD','Mar–May, Oct–Nov',2,'arid',4,NULL,NULL,'culture,food,history',1795037525681,1795071822842);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv76000h13nrvui29z81','singapore','Singapore','Singapore',NULL,1.3521,103.8198,'Singapore is a city-state of remarkable efficiency and diversity. Its Peranakan heritage, hawker food culture, futuristic Gardens by the Bay, and seamless public transport make it one of Asia''s most compelling destinations.','https://images.unsplash.com/photo-1525625293386-3f8f99389edd?w=1600&q=80','https://images.unsplash.com/photo-1525625293386-3f8f99389edd?w=640&q=80','Swapnil Bapat on Unsplash','Marina Bay Sands and Gardens by the Bay at night in Singapore','SGD','Feb–Apr',4,'tropical',5,NULL,NULL,'food,culture,shopping',1795037525683,1795071822843);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv78000i13nre6kphmez','rome-italy','Rome','Italy','Lazio',41.9028,12.4964,'Rome is a living museum — ancient ruins stand alongside baroque fountains and Renaissance churches, all woven into a modern city of outstanding food and street life. No other city contains so many layers of Western history.','https://images.unsplash.com/photo-1529154036614-a60975f5c760?w=1600&q=80','https://images.unsplash.com/photo-1529154036614-a60975f5c760?w=640&q=80','Caleb Miller on Unsplash','The Colosseum in Rome illuminated at night','EUR','Apr–May, Sep–Oct',3,'mediterranean',5,NULL,NULL,'culture,history,food',1795037525684,1795071822844);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv79000j13nr9wwqo9mp','bangkok-thailand','Bangkok','Thailand','Central Thailand',13.7563,100.5018,'Bangkok is a city of intense contrasts — gleaming Buddhist temples next to rooftop bars, canals threading through skyscraper districts, and street food that rivals fine dining. It is a city that rewards those who wander.','https://images.unsplash.com/photo-1508009603885-50cf7c579365?w=1600&q=80','https://images.unsplash.com/photo-1508009603885-50cf7c579365?w=640&q=80','Jack Hunter on Unsplash','Wat Arun temple at sunrise on the Chao Phraya River','THB','Nov–Feb',2,'tropical',5,NULL,NULL,'culture,food,nightlife,history',1795037525685,1795071822846);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmmzv7a000k13nr8yxc0g1j','barcelona-spain','Barcelona','Spain','Catalonia',41.3851,2.1734,'Barcelona is the capital of Catalonia and one of Europe''s most distinctive cities — shaped by Gaudi''s surreal architecture, a 4km beachfront, vibrant food markets, and a cultural identity that proudly holds its own alongside Spain.','https://images.unsplash.com/photo-1583422409516-2895a77efded?w=1600&q=80','https://images.unsplash.com/photo-1583422409516-2895a77efded?w=640&q=80','Florian Wehde on Unsplash','La Sagrada Familia basilica by Gaudi in Barcelona','EUR','May–Jun, Sep–Oct',3,'mediterranean',5,NULL,NULL,'culture,food,relaxation,nightlife',1795037525687,1795071822847);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh42000lczcgwnozc49a','tokyo-japan','Tokyo','Japan','Kanto',35.6762,139.6503,'Tokyo is a city of relentless energy and extraordinary contrasts — ancient shrines between skyscrapers, serene gardens beside neon arcades. The world''s largest metropolitan area is also one of its safest and most logistically impressive.','https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?w=1600&q=80','https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?w=640&q=80','Louie Martinez on Unsplash','Tokyo skyline at night with illuminated skyscrapers','JPY','Mar–May, Sep–Nov',3,'temperate',5,NULL,NULL,'culture,food,urban,technology',1795038673827,1795071822848);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh44000oczcgex25eam3','dubai-uae','Dubai','United Arab Emirates','Arabian Peninsula',25.2048,55.2708,'Dubai is a city of superlatives — the world''s tallest building, some of its largest shopping malls, and an airport that rivals small nations. The desert city has built itself into a global hub for business and tourism in under five decades.','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?w=1600&q=80','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?w=640&q=80','David Rodrigo on Unsplash','Dubai skyline with Burj Khalifa dominating the horizon','AED','Nov–Mar',4,'arid',4,'Alcohol is served in licensed hotels and restaurants only. Public intoxication is illegal.','UAE Government portal','luxury,urban,architecture,desert',1795038673829,1795071822849);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh46000rczcgennczhqd','lisbon-portugal','Lisbon','Portugal','Western Europe',38.7169,-9.1399,'Lisbon is one of Europe''s oldest and most characterful capitals, spread across seven hills with terracotta rooftops, yellow trams, and the world''s greatest tradition of melancholic music — fado. The Atlantic coast sits within an hour''s drive.','https://images.unsplash.com/photo-1555881400-74d7acaacd8b?w=1600&q=80','https://images.unsplash.com/photo-1555881400-74d7acaacd8b?w=640&q=80','Micael Widell on Unsplash','Colourful trams on a hilly Lisbon street','EUR','Mar–May, Sep–Oct',2,'mediterranean',4,NULL,NULL,'culture,food,history,relaxation',1795038673830,1795071822851);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh47000uczcgil1m6zab','london-england','London','United Kingdom','Western Europe',51.5074,-0.1278,'London is one of the world''s most visited cities, blending over two thousand years of history with contemporary culture, finance, and arts. From the Tower of London to Tate Modern, the city compresses extraordinary range into a walkable core.','https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?w=1600&q=80','https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?w=640&q=80','Benjamin Davies on Unsplash','Tower Bridge over the Thames in London','GBP','May–Sep',4,'temperate oceanic',4,NULL,NULL,'culture,history,arts,urban',1795038673832,1795071822852);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh49000wczcgj7ygo5gz','mexico-city-mexico','Mexico City','Mexico','Latin America',19.4326,-99.1332,'Mexico City is a 2,000-year-old megacity built over a drained lake, home to the world''s largest urban archaeology site, one of the world''s best restaurant scenes, and over 150 museums — more than any other city on earth.','https://images.unsplash.com/photo-1518105779142-d975f22f1b0a?w=1600&q=80','https://images.unsplash.com/photo-1518105779142-d975f22f1b0a?w=640&q=80','Victor Garcia on Unsplash','Colourful buildings of Mexico City at dusk','MXN','Nov–Mar',2,'subtropical highland',5,'Exercise normal precautions. Stick to well-known neighbourhoods (Roma, Condesa, Polanco) especially at night.','UK Foreign Travel Advice / US State Dept','culture,food,history,arts',1795038673833,1795071822853);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh4a000yczcgjvm2ekfc','sydney-australia','Sydney','Australia','Oceania',-33.8688,151.2093,'Sydney is Australia''s largest city, defined by its spectacular harbour, two of the world''s most iconic buildings, and a year-round outdoor lifestyle that takes advantage of 300 days of sunshine and some of the world''s best surf beaches.','https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?w=1600&q=80','https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?w=640&q=80','Dan Freeman on Unsplash','Sydney Opera House and Harbour Bridge at sunrise','AUD','Sep–Nov, Mar–May',3,'oceanic',4,NULL,NULL,'beach,outdoor,urban,food',1795038673835,1795071822854);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh4c0010czcgb4a7skx9','jaipur-india','Jaipur','India','South Asia',26.9124,75.7873,'Jaipur, the Pink City, is Rajasthan''s capital and a living showcase of Mughal and Rajput architecture. The old walled city — painted terracotta pink by royal decree in 1876 — is a UNESCO World Heritage Site anchored by the hilltop Amber Fort.','https://images.unsplash.com/photo-1599661046289-e31897846e41?w=1600&q=80','https://images.unsplash.com/photo-1599661046289-e31897846e41?w=640&q=80','Yash Raut on Unsplash','Hawa Mahal palace facade in Jaipur, the Palace of the Winds','INR','Oct–Mar',1,'semi-arid',4,NULL,NULL,'culture,history,architecture,food',1795038673836,1795071822855);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh4d0013czcgkprajclv','amsterdam-netherlands','Amsterdam','Netherlands','Western Europe',52.3676,4.9041,'Amsterdam is a city of 165 canals, 1,500 bridges, and more bicycles than people. The Golden Age architecture, world-class museums — the Rijksmuseum, Van Gogh Museum, Anne Frank House — and liberal culture make it one of Europe''s most visited capitals.','https://images.unsplash.com/photo-1534351590666-13e3e96b5017?w=1600&q=80','https://images.unsplash.com/photo-1534351590666-13e3e96b5017?w=640&q=80','Adrien Olichon on Unsplash','Amsterdam canal houses reflected in the water at dusk','EUR','Apr–May, Sep–Oct',3,'temperate oceanic',3,NULL,NULL,'culture,history,cycling,arts',1795038673837,1795071822857);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh4e0015czcg4n865nqi','prague-czechia','Prague','Czechia','Central Europe',50.0755,14.4378,'Prague is one of Europe''s best-preserved medieval cities — a skyline of Gothic spires, Baroque domes, and Art Nouveau façades, virtually untouched by World War II. The old town and castle district are a UNESCO World Heritage Site.','https://images.unsplash.com/photo-1541849546-216549ae216d?w=1600&q=80','https://images.unsplash.com/photo-1541849546-216549ae216d?w=640&q=80','Kai Pilger on Unsplash','Prague Old Town Square with the Astronomical Clock','CZK','May–Jun, Sep',2,'temperate',3,NULL,NULL,'history,architecture,culture,food',1795038673839,1795071822858);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh4g0017czcggetq1pgn','rio-de-janeiro-brazil','Rio de Janeiro','Brazil','Latin America',-22.9068,-43.1729,'Rio de Janeiro is one of the world''s most scenically dramatic cities — rainforest meets ocean, flanked by granite peaks, with Copacabana and Ipanema beaches at its feet. The city hosts the world''s largest carnival celebration and is Brazil''s cultural capital.','https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=1600&q=80','https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=640&q=80','Agustín Lautaro on Unsplash','Christ the Redeemer statue overlooking Rio de Janeiro','BRL','Mar–Jun, Aug–Oct',2,'tropical',4,'Petty theft is common in tourist areas. Avoid displaying valuables. Some favela areas are unsafe for independent travellers.','UK Foreign Travel Advice','beach,culture,outdoor,food',1795038673840,1795071822859);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh4h0019czcgnixqbs0r','vienna-austria','Vienna','Austria','Central Europe',48.2082,16.3738,'Vienna was the capital of the Austro-Hungarian Empire for 600 years, and that history saturates every boulevard, palace, and coffeehouse. The city consistently ranks first in global quality-of-life surveys — extraordinary culture, food, and public infrastructure in one place.','https://images.unsplash.com/photo-1516550893923-42d28e5677af?w=1600&q=80','https://images.unsplash.com/photo-1516550893923-42d28e5677af?w=640&q=80','Jacek Dylag on Unsplash','Schönbrunn Palace in Vienna surrounded by formal gardens','EUR','Apr–May, Sep–Oct',3,'temperate',4,NULL,NULL,'culture,history,music,arts',1795038673842,1795071822861);
INSERT OR IGNORE INTO "Destination" VALUES('cmwmnoh4j001bczcgb9o47cb2','kathmandu-nepal','Kathmandu','Nepal','South Asia',27.7172,85.324,'Kathmandu is the gateway to the Himalayas — a chaotic, spiritual, and deeply atmospheric city where Buddhist stupas and Hindu temples coexist on adjacent streets. The Kathmandu Valley is a UNESCO World Heritage Site containing seven monument zones.','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1600&q=80','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=640&q=80','Daniel Prudek on Unsplash','Boudhanath Stupa surrounded by prayer flags in Kathmandu','NPR','Oct–Nov, Mar–May',1,'subtropical highland',3,NULL,NULL,'adventure,culture,trekking,spirituality',1795038673843,1795071822862);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2m001e92ihd94f22o8','san-francisco-usa','San Francisco','USA','California',37.7749,-122.4194,'San Francisco is a city of dramatic hills, iconic bridges, and a vibrant tech-meets-bohemian culture. From Fisherman''s Wharf to the Mission District, it offers world-class food, art, and bay views.','https://images.unsplash.com/photo-1501594907352-04cda38ebc29?w=1600&q=80','https://images.unsplash.com/photo-1501594907352-04cda38ebc29?w=640&q=80','Maarten van den Heuvel on Unsplash','Golden Gate Bridge in San Francisco at sunset','USD','Sep–Nov',4,'temperate',5,NULL,NULL,'culture,food,nature,history',1795071822863,1795071822863);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2o001f92ih9v1wa5sn','los-angeles-usa','Los Angeles','USA','California',34.0522,-118.2437,'Los Angeles is the entertainment capital of the world — home to Hollywood, Venice Beach, Griffith Observatory, and an extraordinary dining scene spanning every cuisine imaginable.','https://images.unsplash.com/photo-1534190760961-74e8c1c5c3da?w=1600&q=80','https://images.unsplash.com/photo-1534190760961-74e8c1c5c3da?w=640&q=80','Dex Ezekiel on Unsplash','Los Angeles skyline at dusk with palm trees','USD','Mar–May, Sep–Nov',4,'mediterranean',5,NULL,NULL,'culture,food,nightlife,relaxation',1795071822864,1795071822864);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2p001g92ihj7rl4d0p','chicago-usa','Chicago','USA','Illinois',41.8781,-87.6298,'Chicago is a city of bold architecture, deep-dish pizza, jazz and blues clubs, and world-class museums. The Magnificent Mile, Millennium Park, and Lake Michigan waterfront define its skyline.','https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1600&q=80','https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=640&q=80','Pedro Lastra on Unsplash','Chicago skyline reflected in Lake Michigan','USD','May–Sep',3,'continental',5,NULL,NULL,'culture,food,history,nightlife',1795071822865,1795071822865);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2q001h92ihafodvzee','miami-usa','Miami','USA','Florida',25.7617,-80.1918,'Miami blends Art Deco glamour, Latin culture, and pristine beaches. South Beach, Wynwood''s murals, Little Havana''s cigar shops, and an explosive nightlife scene make it endlessly exciting.','https://images.unsplash.com/photo-1506966953602-c20cc11f75e3?w=1600&q=80','https://images.unsplash.com/photo-1506966953602-c20cc11f75e3?w=640&q=80','Gabriel Garcia Marengo on Unsplash','Miami South Beach colorful Art Deco buildings','USD','Nov–Apr',4,'tropical',5,NULL,NULL,'culture,food,nightlife,relaxation,adventure',1795071822867,1795071822867);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2s001i92ih8fqw69nr','las-vegas-usa','Las Vegas','USA','Nevada',36.1699,-115.1398,'Las Vegas is the entertainment capital of the American Southwest — a desert oasis of world-class shows, celebrity-chef restaurants, luxury resorts, and the neon-lit Strip that never sleeps.','https://images.unsplash.com/photo-1605833556294-ea5c7a74f57d?w=1600&q=80','https://images.unsplash.com/photo-1605833556294-ea5c7a74f57d?w=640&q=80','Zac Bromell on Unsplash','Las Vegas Strip at night with illuminated casinos','USD','Mar–May, Sep–Nov',3,'desert',4,NULL,NULL,'nightlife,food,culture,activity',1795071822868,1795071822868);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2t001j92ihge8apzbo','new-orleans-usa','New Orleans','USA','Louisiana',29.9511,-90.0715,'New Orleans is a city unlike any other — Creole cuisine, jazz pouring out of Bourbon Street clubs, Mardi Gras beads, and a French Quarter that holds centuries of layered history and culture.','https://images.unsplash.com/photo-1570197571499-166b36435e9f?w=1600&q=80','https://images.unsplash.com/photo-1570197571499-166b36435e9f?w=640&q=80','Jack Finnigan on Unsplash','New Orleans French Quarter at night with jazz clubs','USD','Feb–May',2,'subtropical',5,NULL,NULL,'culture,food,history,nightlife',1795071822869,1795071822869);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2v001k92ihdcknudcw','seattle-usa','Seattle','USA','Washington',47.6062,-122.3321,'Seattle is a Pacific Northwest gem of coffee culture, Pike Place Market, the Space Needle, and lush green surroundings. It''s the gateway to Olympic National Park and the Cascades.','https://images.unsplash.com/photo-1502175353174-a7a70e73b362?w=1600&q=80','https://images.unsplash.com/photo-1502175353174-a7a70e73b362?w=640&q=80','Zhifei Zhou on Unsplash','Seattle Space Needle with Mount Rainier in background','USD','Jun–Sep',3,'oceanic',4,NULL,NULL,'culture,food,nature,history',1795071822871,1795071822871);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2w001l92iheq5c8rm1','washington-dc-usa','Washington D.C.','USA','District of Columbia',38.9072,-77.0369,'Washington D.C. is the seat of American democracy — home to the National Mall, Smithsonian museums (all free), the Lincoln Memorial, and the vibrant neighborhoods of Georgetown and Adams Morgan.','https://images.unsplash.com/photo-1501466044931-62695aada8e9?w=1600&q=80','https://images.unsplash.com/photo-1501466044931-62695aada8e9?w=640&q=80','David Everett Strickler on Unsplash','Washington DC Lincoln Memorial and Reflecting Pool','USD','Mar–Jun, Sep–Nov',3,'humid subtropical',4,NULL,NULL,'culture,history,food',1795071822872,1795071822872);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2x001m92ihp57nr9vy','boston-usa','Boston','USA','Massachusetts',42.3601,-71.0589,'Boston is America''s walking city — follow the Freedom Trail through Revolutionary War history, cheer at Fenway Park, dine on clam chowder in the North End, and explore world-class universities.','https://images.unsplash.com/photo-1569260135684-b367de0a7e4b?w=1600&q=80','https://images.unsplash.com/photo-1569260135684-b367de0a7e4b?w=640&q=80','Caleb Perez on Unsplash','Boston cityscape with historic brownstones','USD','May–Oct',4,'continental',4,NULL,NULL,'history,culture,food',1795071822873,1795071822873);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2y001n92ihe4jod7gi','nashville-usa','Nashville','USA','Tennessee',36.1627,-86.7816,'Nashville is Music City — home of country music, honky-tonk bars on Broadway, legendary recording studios, and a booming food scene with hot chicken, BBQ, and James Beard-winning restaurants.','https://images.unsplash.com/photo-1619221882220-947b3d3c8861?w=1600&q=80','https://images.unsplash.com/photo-1619221882220-947b3d3c8861?w=640&q=80','Courtney Cook on Unsplash','Nashville Broadway honky-tonk bars lit up at night','USD','Apr–Jun, Sep–Oct',3,'humid subtropical',4,NULL,NULL,'culture,food,nightlife,history',1795071822874,1795071822874);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez2z001o92ihqekbsz0y','austin-usa','Austin','USA','Texas',30.2672,-97.7431,'Austin keeps it weird — a live music mecca, tech hub, and foodie paradise all in one. Sixth Street''s clubs, South Congress Avenue''s boutiques, and legendary BBQ joints define this Texas capital.','https://images.unsplash.com/photo-1531218150217-54595bc2b934?w=1600&q=80','https://images.unsplash.com/photo-1531218150217-54595bc2b934?w=640&q=80','Pete Alexopoulos on Unsplash','Austin Texas skyline at sunset with Congress Avenue bridge','USD','Mar–May, Oct–Nov',3,'subtropical',5,NULL,NULL,'food,nightlife,culture,nature',1795071822875,1795071822875);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez30001p92ih1p7qlid1','honolulu-usa','Honolulu','USA','Hawaii',21.3069,-157.8583,'Honolulu is the gateway to Hawaii — Waikiki''s famous beach, Diamond Head crater hikes, the Pearl Harbor memorial, and a food scene blending Polynesian, Japanese, and American flavors.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1600&q=80','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=640&q=80','Sean Oulashin on Unsplash','Waikiki beach in Honolulu with Diamond Head in background','USD','Apr–Oct',4,'tropical',4,NULL,NULL,'relaxation,nature,culture,food,adventure',1795071822876,1795071822876);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez31001q92ihf0brydo8','denver-usa','Denver','USA','Colorado',39.7392,-104.9903,'Denver sits at the foot of the Rocky Mountains — a mile-high city famous for craft beer, Red Rocks Amphitheatre, the vibrant RiNo art district, and world-class skiing just 90 minutes away.','https://images.unsplash.com/photo-1476059153217-32a4c7f8e72e?w=1600&q=80','https://images.unsplash.com/photo-1476059153217-32a4c7f8e72e?w=640&q=80','Jonathan Mast on Unsplash','Denver Colorado skyline with Rocky Mountains in background','USD','Jun–Aug, Dec–Feb',3,'semi-arid',4,NULL,NULL,'adventure,nature,culture,food',1795071822878,1795071822878);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez33001r92ihbanox4ww','portland-usa','Portland','USA','Oregon',45.5051,-122.675,'Portland is America''s most eccentric city — Powell''s Books, food cart pods on every corner, the Pearl District''s galleries, Forest Park''s trails, and the finest craft breweries in the Pacific Northwest.','https://images.unsplash.com/photo-1540314783767-db64b97e9b16?w=1600&q=80','https://images.unsplash.com/photo-1540314783767-db64b97e9b16?w=640&q=80','Zach Lisko on Unsplash','Portland Oregon cityscape with Mount Hood in distance','USD','Jun–Sep',2,'oceanic',5,NULL,NULL,'food,culture,nature,shopping',1795071822879,1795071822879);
INSERT OR IGNORE INTO "Destination" VALUES('cmwn7ez34001s92ihcpkxfmbv','charleston-usa','Charleston','USA','South Carolina',32.7765,-79.9311,'Charleston is one of America''s most beautiful cities — antebellum mansions, cobblestone streets, Lowcountry cuisine (shrimp and grits, she-crab soup), and some of the South''s most storied history.','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1600&q=80','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=640&q=80','David Veksler on Unsplash','Charleston South Carolina colorful Rainbow Row houses','USD','Mar–May, Sep–Nov',3,'humid subtropical',5,NULL,NULL,'history,food,culture,relaxation',1795071822881,1795071822881);

